import { basename } from 'pathe';

import { CompressedChunk } from './compressed-chunk';
import { logWrittenFile, splatModelComment } from './utils';
import { type ChunkSource, type ChunkDataPool } from '../chunk';
import { materializeToDataTable } from '../compat/data-table';
import { DataTable, sortMortonOrder, convertToSpace, getSHBands, shRestNames } from '../data-table';
import { type FileSystem } from '../io/write';
import { type SplatModel } from '../splat-model';
import { logger, Transform } from '../utils';
import { version } from '../version';

const generatedByString = `Generated by splat-transform ${version}`;

const chunkProps = [
    'min_x', 'min_y', 'min_z',
    'max_x', 'max_y', 'max_z',
    'min_scale_x', 'min_scale_y', 'min_scale_z',
    'max_scale_x', 'max_scale_y', 'max_scale_z',
    'min_r', 'min_g', 'min_b',
    'max_r', 'max_g', 'max_b'
];

const vertexProps = [
    'packed_position',
    'packed_rotation',
    'packed_scale',
    'packed_color'
];

// Size of a chunk in the compressed PLY format (number of splats per chunk)
const CHUNK_SIZE = 256;

type WriteCompressedPlyOptions = {
    filename: string;
    dataTable: DataTable;
    model?: SplatModel;
};

/**
 * Writes Gaussian splat data to compressed PLY format.
 *
 * Uses quantization and chunking to reduce file size while maintaining
 * compatibility with PLY-based viewers. Data is sorted using Morton order
 * for better compression and streaming performance.
 *
 * @param options - Options including filename and data table to write.
 * @param fs - File system for writing the output file.
 * @ignore
 */
const writeCompressedPly = async (options: WriteCompressedPlyOptions, fs: FileSystem) => {
    const { filename } = options;
    const dataTable = convertToSpace(options.dataTable, Transform.PLY);

    const shBands = getSHBands(dataTable);
    const outputSHCoeffs = [0, 3, 8, 15][shBands];

    const numSplats = dataTable.numRows;
    const numChunks = Math.ceil(numSplats / CHUNK_SIZE);

    const shHeader = shBands ? [
        `element sh ${numSplats}`,
        new Array(outputSHCoeffs * 3).fill('').map((_, i) => `property uchar f_rest_${i}`)
    ].flat() : [];

    // The packed layout is fixed, so a 2DGS scene keeps its (materialized) third
    // scale — the comment is what tells a viewer to ignore it.
    const modelComment = splatModelComment(options.model ?? 'default');

    const headerText = [
        'ply',
        'format binary_little_endian 1.0',
        `comment ${generatedByString}`,
        ...(modelComment ? [`comment ${modelComment}`] : []),
        `element chunk ${numChunks}`,
        chunkProps.map(p => `property float ${p}`),
        `element vertex ${numSplats}`,
        vertexProps.map(p => `property uint ${p}`),
        shHeader,
        'end_header\n'
    ].flat().join('\n');

    const header = (new TextEncoder()).encode(headerText);
    const chunkData = new Float32Array(numChunks * chunkProps.length);
    const splatIData = new Uint32Array(numSplats * vertexProps.length);
    const shData = new Uint8Array(numSplats * outputSHCoeffs * 3);

    // sort splats into some kind of order (morton order rn)
    const sortIndices = new Uint32Array(dataTable.numRows);
    for (let i = 0; i < sortIndices.length; ++i) {
        sortIndices[i] = i;
    }
    sortMortonOrder(dataTable, sortIndices);

    const row: any = {};

    const chunk = new CompressedChunk();

    for (let i = 0; i < numChunks; ++i) {
        const num = Math.min(numSplats, (i + 1) * CHUNK_SIZE) - i * CHUNK_SIZE;
        for (let j = 0; j < num; ++j) {
            const index = sortIndices[i * CHUNK_SIZE + j];

            // read splat data
            dataTable.getRow(index, row);

            // update chunk
            chunk.set(j, row);

            // quantize and write sh data
            let off = (i * CHUNK_SIZE + j) * outputSHCoeffs * 3;
            for (let k = 0; k < outputSHCoeffs * 3; ++k) {
                const nvalue = row[shRestNames[k]] / 8 + 0.5;
                shData[off++] = Math.max(0, Math.min(255, Math.trunc(nvalue * 256)));
            }
        }

        // repeat the last gaussian to fill the rest of the final chunk
        for (let j = num; j < CHUNK_SIZE; ++j) {
            chunk.set(j, row);
        }

        // pack the chunk
        chunk.pack();

        // store the float data
        chunkData.set(chunk.chunkData, i * 18);

        // write packed bits
        const offset = i * CHUNK_SIZE * 4;
        for (let j = 0; j < num; ++j) {
            splatIData[offset + j * 4 + 0] = chunk.position[j];
            splatIData[offset + j * 4 + 1] = chunk.rotation[j];
            splatIData[offset + j * 4 + 2] = chunk.scale[j];
            splatIData[offset + j * 4 + 3] = chunk.color[j];
        }
    }

    const writingGroup = logger.group('Writing');

    const writer = await fs.createWriter(filename);
    await writer.write(header);
    await writer.write(new Uint8Array(chunkData.buffer));
    await writer.write(new Uint8Array(splatIData.buffer));
    await writer.write(shData);
    await writer.close();

    logWrittenFile(basename(filename), writer.bytesWritten);
    writingGroup.end();
};

/**
 * `ChunkSource` adapter over {@link writeCompressedPly}. Compressed PLY is a
 * legacy output format, so rather than a streaming encoder this **materializes**
 * the source to a `DataTable` (memory-inefficient by design — acceptable here)
 * and delegates. New code should prefer SOG.
 *
 * @param source - The source to encode (its pending transform is baked to PLY space by the underlying writer).
 * @param pool - Pool for the temporary read buffers used while materializing.
 * @param options - Output options (filename).
 * @param fs - File system to write through.
 * @ignore
 */
const writeCompressedPlySource = async (
    source: ChunkSource,
    pool: ChunkDataPool,
    options: { filename: string },
    fs: FileSystem
): Promise<void> => {
    const dataTable = await materializeToDataTable(source, pool);
    await writeCompressedPly({ filename: options.filename, dataTable, model: source.meta.model }, fs);
};

export { writeCompressedPly, writeCompressedPlySource };
